svg.script:
(() => {
  const root = document.getElementById("heilbronn-abb13979507a");
  if (!root) return;
  const triangles = Array.from(root.querySelectorAll('.limiting-fill'));
  const edges = Array.from(root.querySelectorAll('.triangle-edge'));
  const points = Array.from(root.querySelectorAll('.point'));
  const status = root.querySelector('.selection-status');
  let locked = null;

  const sameFocus = (a, b) => Boolean(a && b && a.type === b.type && a.id === b.id);
  const triangleIdsForPoint = index => new Set(
    triangles.filter(item => item.dataset.points.split(' ').includes(String(index)))
      .map(item => item.dataset.triangleId)
  );
  const triangleIdsForClass = index => new Set(
    triangles.filter(item => item.dataset.classIndex === String(index))
      .map(item => item.dataset.triangleId)
  );
  const triangleWord = count => count === 1 ? 'triangle' : 'triangles';

  function updateStatus(focus, active) {
    if (!status) return;
    if (!focus) { status.textContent = ''; return; }
    if (focus.type === 'point') {
      status.textContent = `Point ${focus.id} — ${active.size} limiting ${triangleWord(active.size)}`;
      return;
    }
    if (focus.type === 'class') {
      status.textContent = `Class ${focus.id} — ${active.size} limiting ${triangleWord(active.size)}`;
      return;
    }
    const item = triangles.find(triangle => triangle.dataset.triangleId === focus.id);
    if (!item) { status.textContent = ''; return; }
    const pointsText = item.dataset.points.split(' ').join(', ');
    const kind = item.dataset.exactMinimum === 'true' ? 'exact minimum' : 'near minimum';
    status.textContent = `Triangle (${pointsText}) — ${kind} — class ${item.dataset.classIndex}`;
  }

  function applyFocus(focus) {
    let active = new Set();
    if (focus?.type === 'triangle') active.add(focus.id);
    if (focus?.type === 'point') active = triangleIdsForPoint(focus.id);
    if (focus?.type === 'class') active = triangleIdsForClass(focus.id);
    root.classList.toggle('has-focus', active.size > 0);
    triangles.forEach(item => item.classList.toggle('is-active', active.has(item.dataset.triangleId)));
    edges.forEach(edge => {
      const members = edge.dataset.triangles.split(' ');
      edge.classList.toggle('is-active', members.some(id => active.has(id)));
    });
    const focusPoints = new Set();
    triangles.filter(item => active.has(item.dataset.triangleId)).forEach(item => {
      item.dataset.points.split(' ').forEach(index => focusPoints.add(index));
    });
    points.forEach(point => {
      const index = point.dataset.pointIndex;
      point.classList.toggle('is-focus-member', focusPoints.has(index));
      point.classList.toggle('is-selected', focus?.type === 'point' && String(focus.id) === index);
    });
    updateStatus(focus, active);
  }

  function preview(focus) { if (!locked) applyFocus(focus); }
  function endPreview() { if (!locked) applyFocus(null); }
  function toggleLock(focus) {
    locked = sameFocus(locked, focus) ? null : focus;
    applyFocus(locked);
  }

  triangles.forEach(item => {
    const focus = {type: 'triangle', id: item.dataset.triangleId};
    const classFocus = {type: 'class', id: Number(item.dataset.classIndex)};
    item.addEventListener('pointerenter', () => preview(focus));
    item.addEventListener('pointerleave', endPreview);
    item.addEventListener('click', event => {
      event.stopPropagation();
      toggleLock(event.shiftKey ? classFocus : focus);
    });
  });
  points.forEach(point => {
    const focus = {type: 'point', id: Number(point.dataset.pointIndex)};
    point.addEventListener('pointerenter', () => preview(focus));
    point.addEventListener('pointerleave', endPreview);
    point.addEventListener('click', event => { event.stopPropagation(); toggleLock(focus); });
  });
  root.addEventListener('click', event => {
    if (event.target === root || event.target.classList.contains('frame')) {
      locked = null;
      applyFocus(null);
    }
  });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') { locked = null; applyFocus(null); }
  });
})();
